// Keywords that trigger removal (Management, Leadership, and non-IC roles)
const managementKeywords = [
  'director', 'vp', 'vice president', 'head of', 'chief',
  'manager', 'team lead', 'people lead', 'supervisor', 'lead'
];

// Explicitly excluded roles (AEs, BDRs, SDRs, BDMs, Sales Reps, Value Engineers, Architects)
const excludedRoleKeywords = [
  // Pipeline Generation & Sales Reps
  'bdr', 'sdr', 'bdm', 
  'business development representative', 'sales development representative',
  'business development manager', 'business development',
  'sales representative', 'sales rep',

  // Quota-Carrying Account Executives
  'account executive', 'ae', 'account rep', 'account representative',

  // Specifically Excluded Pre-Sales Sub-Types
  'value engineer', 'value engineering',
  'solutions architect', 'solution architect',
  'forward deployed engineer', 'forward-deployed engineer'
];

// Specific roles where Senior / Principal titles MUST be excluded
const seniorExcludedRoles = [
  'sales engineer', 'solutions engineer',
  'solutions consultant', 'pre-sales', 'presales'
];

// Target IC Role Keywords - STRICTLY Technical Pre-Sales & Solutions Engineering ONLY
const targetRoleKeywords = [
  'sales engineer',
  'solutions engineer',
  'solutions consultant',
  'pre-sales',
  'presales',
  'pre-sales engineer',
  'pre sales engineer'
];

// STRICT ALLOWLIST for On-Site and Hybrid roles (NYC Metro, Texas, Florida Hubs)
const allowedLocations = [
  // New York / NYC Metro Area
  'new york', 'nyc', 'manhattan', 'brooklyn', 'queens', 'bronx', 'staten island', 'jersey city', 'hoboken', 'ny',

  // Texas (State & Major Tech Hubs)
  'texas', 'tx', 'austin', 'dallas', 'houston', 'fort worth', 'san antonio', 'plano', 'frisco', 'irving',

  // Florida (State & Major Tech Hubs)
  'florida', 'fl', 'miami', 'orlando', 'tampa', 'fort lauderdale', 'jacksonville', 'west palm beach', 'boca raton'
];

const filteredItems = [];

for (const item of $input.all()) {
  const job = item.json;
  const title = String(job.title || '').toLowerCase();
  const rawWorkplace = String(job.workplaceType || job.workplace_type || '').toLowerCase();
  const location = String(job.location || '').toLowerCase();
  const description = String(job.description || '').toLowerCase();
  const fullText = `${location} ${rawWorkplace} ${title} ${description}`;

  // 1. Exclude AEs, BDRs, SDRs, BDMs, Sales Reps, Value Engineers, and Architects Immediately
  const isExcludedRole = excludedRoleKeywords.some(keyword => {
    const regex = new RegExp(`\\b${keyword}\\b`, 'i');
    return regex.test(title);
  });
  if (isExcludedRole) continue;

  // 2. Exclude Senior / Principal titles for SE / Pre-Sales
  const hasSeniorOrPrincipal = /\b(senior|sr|sr\.|principal)\b/i.test(title);
  if (hasSeniorOrPrincipal) {
    const isAffectedRole = seniorExcludedRoles.some(role => new RegExp(`\\b${role}\\b`, 'i').test(title));
    if (isAffectedRole) continue;
  }

  // 3. Exclude Management & Leadership Titles
  const isManagement = managementKeywords.some(keyword => {
    const regex = new RegExp(`\\b${keyword}\\b`, 'i');
    return regex.test(title);
  });
  if (isManagement) continue;

  // 4. Must match at least one Technical Pre-Sales or Solutions Engineering keyword
  const isTargetIC = targetRoleKeywords.some(keyword => {
    const regex = new RegExp(`\\b${keyword}\\b`, 'i');
    return regex.test(title);
  });
  if (!isTargetIC) continue;

  // 5. Classify Workplace Type (Remote, Hybrid, On-Site)
  let normalizedWorkplace = 'On-Site'; // Default fallback
  if (rawWorkplace.includes('remote') || location.includes('remote') || title.includes('remote')) {
    normalizedWorkplace = 'Remote';
  } else if (rawWorkplace.includes('hybrid') || location.includes('hybrid') || title.includes('hybrid') || description.includes('hybrid')) {
    normalizedWorkplace = 'Hybrid';
  } else if (rawWorkplace.includes('on-site') || rawWorkplace.includes('onsite') || rawWorkplace.includes('in-office')) {
    normalizedWorkplace = 'On-Site';
  }

  // 6. Allowlist Filter: Remote is ALWAYS accepted. On-Site/Hybrid MUST be in NYC Metro, Texas, or Florida.
  if (normalizedWorkplace !== 'Remote') {
    const isAllowedLocation = allowedLocations.some(loc => {
      const regex = new RegExp(`\\b${loc}\\b`, 'i');
      return regex.test(location) || regex.test(fullText);
    });

    if (!isAllowedLocation) {
      continue; // Drops jobs outside NYC Metro, Texas, or Florida
    }
  }

  // Pass allowed items forward with normalized workplace attribute
  filteredItems.push({
    json: {
      ...job,
      workplaceTypeNormalized: normalizedWorkplace
    }
  });
}

return filteredItems;

for (const item of $input.all()) {
  const rawText = item.json.text || item.json.output || '';
  const cleanedText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();

