    const parsed = JSON.parse(cleanedText);

    // Helper function to safely truncate skills to ~85% line fill (75 chars)
    // Backtracks to the last comma so no incomplete phrase or trailing comma is left
    function formatSkillsString(str) {
      if (!str) return "";
      let trimmed = str.trim();

      // Return clean if already within the 85% fill limit (75 chars)
      if (trimmed.length <= 75) return trimmed.replace(/,\s*$/, '');

      // Cut down at max limit
      let sliced = trimmed.substring(0, 75);

      // Backtrack to the last comma to drop the overflowing skill completely
      const lastComma = sliced.lastIndexOf(',');
      if (lastComma > 0) {
        sliced = sliced.substring(0, lastComma);
      } else {
        // Fallback to last space if no comma is found
        const lastSpace = sliced.lastIndexOf(' ');
        if (lastSpace > 0) sliced = sliced.substring(0, lastSpace);
      }

      return sliced.replace(/,\s*$/, '').trim();
    }

    // Helper function to remove trailing periods from bullet arrays
    const cleanBullets = (bulletObj) => {
      const sanitized = {};
      for (const [key, bullets] of Object.entries(bulletObj)) {
        if (Array.isArray(bullets)) {
          sanitized[key] = bullets.map(b => typeof b === 'string' ? b.replace(/\.$/, '').trim() : b);
        } else {
          sanitized[key] = bullets;
        }
      }
      return sanitized;
    };

