  const recruiterTitles = ['recruiter', 'talent', 'acquisition', 'sourcer', 'people', 'hr'];
  const peerTitles = ['solutions engineer', 'sales engineer', 'pre-sales', 'presales', 'solutions consultant', 'account executive', 'value engineer', 'architect'];

  const selectedTitles = new Set();

  for (const result of people) {
    const person = result.person || result;
    const company = result.company || {};

    // 🔴 ADDED: Check Prospeo's email status and block if not VERIFIED
    const emailData = result.email || person.email || {};
    const emailStatus = String(emailData.status || result.email_status || person.email_status || '').toUpperCase();
    const isVerified = emailStatus === 'VERIFIED';

    if (!isVerified) {
      continue; // Skip contacts that do not have a verified email status
    }

    const title = String(person.current_job_title || person.title || '').toLowerCase().trim();

    // 1. Hiring Manager
    if (!hiringManager && hmTitles.some(k => title.includes(k)) && !recruiterTitles.some(k => title.includes(k))) {
      if (!selectedTitles.has(title)) {
        hiringManager = { ...person, company, emailData, personaType: 'Hiring Manager' };
        selectedTitles.add(title);
        continue;
      }
    }

    // 2. Recruiter
    if (!recruiter && recruiterTitles.some(k => title.includes(k))) {
      if (!selectedTitles.has(title)) {
        recruiter = { ...person, company, emailData, personaType: 'Recruiter' };
        selectedTitles.add(title);
        continue;
      }
    }

    // 3. Peer IC
    if (!peerIC && peerTitles.some(k => title.includes(k)) && !hmTitles.some(k => title.includes(k))) {
      if (!selectedTitles.has(title)) {
        peerIC = { ...person, company, emailData, personaType: 'Peer IC' };
        selectedTitles.add(title);
        continue;
      }
    }

    if (hiringManager && recruiter && peerIC) break;
  }

  const matched = [hiringManager, recruiter, peerIC].filter(Boolean);

  for (const c of matched) {
    finalContacts.push({
      json: {
        prospeoId: c.person_id || c.id,
        name: c.full_name || `${c.first_name || ''} ${c.last_name || ''}`.trim(),
        title: c.current_job_title || c.title,
        personaType: c.personaType,
        linkedinUrl: c.linkedin_url || '',
        companyWebsite: c.company?.company_website || c.company?.website || '',
        organization: c.company?.company_name || c.company?.name || parentCompany,
        email: c.emailData?.email || c.email || c.person_email || '',
        emailStatus: c.emailData?.status || 'VERIFIED',

        // PASSED DIRECTLY ON EVERY CONTACT PAYLOAD FOR AIRTABLE & GEMINI:
        jobRecordId: parentJobRecordId,
        targetJobTitle: parentJobTitle,
        companyName: parentCompany,
        resumePdfUrl: parentResumeUrl,
        jobDescription: parentJobDescription // <--- ACCESSIBLE DIRECTLY BY $json.jobDescription
      }
    });
  }
});

return finalContacts;

